#include <stdio.h>

typedef struct {
    int x;
    int y;
} Point;

int manhattan(Point a, Point b) {
    int dx = a.x - b.x;
    int dy = a.y - b.y;
    if (dx < 0) dx = -dx;
    if (dy < 0) dy = -dy;
    return dx + dy;
}

int main(void) {
    Point p1, p2;
    if (scanf("%d %d", &p1.x, &p1.y) != 2) {
        return 1;
    }
    if (scanf("%d %d", &p2.x, &p2.y) != 2) {
        return 1;
    }
    printf("%d\n", manhattan(p1, p2));
    return 0;
}

