#include <stdio.h>

typedef enum {
    FLAG_A = 1 << 0,
    FLAG_B = 1 << 1,
    FLAG_C = 1 << 2,
    FLAG_D = 1 << 3
} Flag;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    Flag mask = (Flag)0;
    if (n & 1) mask |= FLAG_A;
    if (n & 2) mask |= FLAG_B;
    if (n & 4) mask |= FLAG_C;
    if (n & 8) mask |= FLAG_D;
    int count = 0;
    if (mask & FLAG_A) count++;
    if (mask & FLAG_B) count++;
    if (mask & FLAG_C) count++;
    if (mask & FLAG_D) count++;
    printf("%d\n", count);
    return 0;
}

