    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (scanf("%d", &m[i][j]) != 1) {
                return 1;
            }
        }
    }
    printf("%d\n", trace(m));
    return 0;
}

